steps.code:
# There are 9 friends listed. Including the user (Troy Solomon), that makes 10 people, matching the number of roommates.
# Let's build the roommates list: all 9 friends + the user.
# We'll need to request taxi payments from the 9 friends (excluding the user), and pay Nancy for food.
# Let's extract Nancy's info and the rest of the roommates.

roommates = [
    {
        "first_name": "Denise",
        "last_name": "Maldonado",
        "email": "deniseburch@gmail.com"
    },
    {
        "first_name": "Erica",
        "last_name": "Wilson",
        "email": "eri_powe@gmail.com"
    },
    {
        "first_name": "Kathryn",
        "last_name": "Maldonado",
        "email": "kathrynmaldonado@gmail.com"
    },
    {
        "first_name": "Leslie",
        "last_name": "Ball",
        "email": "les_ball@gmail.com"
    },
    {
        "first_name": "Jose",
        "last_name": "Harrison",
        "email": "joseharr@gmail.com"
    },
    {
        "first_name": "Erika",
        "last_name": "Blackburn",
        "email": "erikabail@gmail.com"
    },
    {
        "first_name": "Nancy",
        "last_name": "Ritter",
        "email": "nan_ritt@gmail.com"
    },
    {
        "first_name": "Miranda",
        "last_name": "Weber",
        "email": "mir-powe@gmail.com"
    },
    {
        "first_name": "Morgan",
        "last_name": "Burton",
        "email": "morgan-harrison@gmail.com"
    }
]

# Find Nancy's info
nancy = next(r for r in roommates if r["first_name"] == "Nancy" and r["last_name"] == "Ritter")
# Roommates to request taxi payment from (exclude self)
taxi_request_roommates = [r for r in roommates if not (r["first_name"] == "Nancy" and r["last_name"] == "Ritter")]

print("Nancy:", nancy)
print("Taxi request roommates:", taxi_request_roommates)

