# The spotify.show_song API takes a single song_id at a time.
# Let's fetch details for all unique song_ids and build a mapping from song_id to (title, artist).
# We'll store all song details in a dictionary for easy lookup.

song_details = {}
for song_id in unique_song_ids:
    song = apis.spotify.show_song(song_id=song_id)
    if "song_id" in song:
        # Use the first artist's name for matching (assuming single artist per song for now)
        artist_name = song["artists"][0]["name"] if song["artists"] else ""
        song_details[song_id] = {
            "title": song["title"],
            "artist": artist_name
        }

print(song_details)

