steps.code:
# Now let's match the old songs (from old_songs) to the songs in the playlists by title and artist.
# We'll build a set of (title.lower().strip(), artist.lower().strip()) for all old songs.
# Then, for each song in the playlists, if its (title, artist) matches, we'll mark it for removal and archiving.

# Assume old_songs is a list of dicts like: [{"title": ..., "artist": ...}, ...]
old_song_keys = set(
    (s["title"].strip().lower(), s["artist"].strip().lower())
    for s in old_songs
)

# Build a mapping from song_id to (title, artist) for all playlist songs
song_id_to_key = {}
for song_id, info in song_details.items():
    for artist in info["artists"]:
        # Each artist gets a separate key for matching
        key = (info["title"].strip().lower(), artist["name"].strip().lower())
        song_id_to_key.setdefault(song_id, set()).add(key)

# Find all song_ids in playlists that match old songs
old_song_ids_to_remove = set()
for song_id, keys in song_id_to_key.items():
    if any(k in old_song_keys for k in keys):
        old_song_ids_to_remove.add(int(song_id))

# For each playlist, find which of its songs are old and need to be removed
playlist_removals = {}
for playlist_id, song_ids in playlist_song_ids.items():
    to_remove = [sid for sid in song_ids if sid in old_song_ids_to_remove]
    if to_remove:
        playlist_removals[playlist_id] = to_remove

print(playlist_removals)  # playlist_id -> list of song_ids to remove and archive

