# We'll use the playlist_id_to_songs mapping to find which playlists contain old songs and prepare a removal plan.

# Placeholder: If old_song_to_spotify_id is not defined, let's prompt for it.
try:
    old_song_spotify_ids = set(entry["song_id"] for entry in old_song_to_spotify_id if entry.get("song_id") is not None)
except NameError:
    old_song_spotify_ids = set()

removal_plan = []
for playlist_id, song_ids in playlist_id_to_songs.items():
    songs_to_remove = list(set(song_ids) & old_song_spotify_ids)
    if songs_to_remove:
        removal_plan.append({
            "playlist_id": playlist_id,
            "songs_to_remove": songs_to_remove
        })

print(removal_plan)

