steps.code:
# Let's build a set of (title, artist) pairs from the archive list for easy matching.
# Then, for each song in song_metadata, check if its (title, artist) matches any in the archive set.
# We'll collect the song_ids that need to be archived.

archive_title_artist_set = set()
for entry in songs_to_archive:
    if " by " in entry:
        title, artist = entry.rsplit(" by ", 1)
        archive_title_artist_set.add((title.strip(), artist.strip()))

# Now, find song_ids in song_metadata that match the archive list
archive_song_ids = []
for song_id, meta in song_metadata.items():
    for artist in meta["artists"]:
        if (meta["title"], artist) in archive_title_artist_set:
            archive_song_ids.append(int(song_id))
            break

print(archive_song_ids)  # These are the song_ids to remove from playlists and add to "Old Songs"

