# Now, let's remove all the songs to archive from all the user's Spotify playlists.
# We'll skip the "Old Songs" playlist (playlist_id=654) to avoid removing from the archive itself.
# We'll collect the results for each removal for logging.

removal_results = []
for playlist in all_playlists:
    if playlist["playlist_id"] == old_songs_playlist_id:
        continue
    for song_id in songs_to_archive_ids:
        result = apis.spotify.remove_song_from_playlist(
            playlist_id=playlist["playlist_id"],
            song_id=song_id,
            access_token=spotify_login["access_token"]
        )
        removal_results.append({
            "playlist_id": playlist["playlist_id"],
            "song_id": song_id,
            "result": result
        })

print(removal_results)

