# Now let's fetch the details for each song_id using spotify.show_song.
# We'll build a mapping from song_id to (title, artist_name) for matching.
song_id_to_info = {}
for song_id in all_song_ids:
    song = apis.spotify.show_song(song_id=song_id)
    # Defensive: Only add if song fetch succeeded and has required fields
    if song and "title" in song and "artists" in song and song["artists"]:
        song_id_to_info[song_id] = {
            "title": song["title"],
            "artists": [artist["name"] for artist in song["artists"]]
        }
print(song_id_to_info)

