    song_title = normalize(song["title"])
    song_artists = set(normalize(a["name"]) for a in song["artists"])
    for old_song in old_songs:
        old_title = normalize(old_song["title"])
        old_artists = set(normalize(a) for a in old_song["artists"])
        # Match if title matches and all old_song artists are in song artists
        if song_title == old_title and old_artists.issubset(song_artists):
            matched_song_ids.append(song["song_id"])
            break

