# We'll collect the song_ids of songs to archive.

def normalize(s):
    return s.strip().lower()

archived_song_ids = []
for song in all_song_details:
    song_title = normalize(song['title'])
    song_artists = set(normalize(a['name']) for a in song['artists'])
    for old_song in old_songs:
        old_title = normalize(old_song['title'])
        old_artists = set(normalize(a) for a in old_song['artists'])
        if song_title == old_title and song_artists == old_artists:
            archived_song_ids.append(song['song_id'])
            break

print(archived_song_ids)

# Next, let's check if a playlist named "Archived Playlist Songs" already exists.
# If not, we will create it. We'll search the playlists by title.

archived_playlist = None
for playlist in playlists:
    if playlist["title"].strip().lower() == "archived playlist songs":
        archived_playlist = playlist
        break

if archived_playlist:
    archived_playlist_id = archived_playlist["playlist_id"]
else:
