# Next, let's check if a playlist named "Archived Playlist Songs" already exists.
# If not, we'll create it. We'll use the playlists variable (already fetched) to check for its existence.

archived_playlist = None
for pl in playlists:
    if pl["title"] == "Archived Playlist Songs":
        archived_playlist = pl
        break

if archived_playlist is None:
    # Need to create the playlist. Let's check the API for creating a playlist.
    print(apis.api_docs.show_api_doc(app_name='spotify', api_name='create_playlist'))
else:
    print(archived_playlist)

