steps.code:
# Now let's search for each song (by title and artist) on Spotify to get their release date.
# We'll use the `search_songs` endpoint with a query like "title artist".
# We'll collect the release month (e.g., "January 2020") for each song.

spotify_release_months = []

for song in songs_missing_month:
    query = f"{song['title']} {song['artist']}"
    # Only fetch the top result for each query
    results = apis.spotify.search_songs(query=query, page_limit=1)
    if results and isinstance(results, list) and len(results) > 0:
        # Try to match artist name exactly if possible
        found = None
        for r in results:
            if any(song['artist'].lower() in a['name'].lower() for a in r.get('artists', [])):
                found = r
                break
        if not found:
            found = results[0]
        release_date = found.get('release_date')
        # Format release month as "Month YYYY"
        if release_date:
            import datetime
            dt = datetime.datetime.fromisoformat(release_date)
            release_month = dt.strftime("%B %Y")
            spotify_release_months.append({
                'title': song['title'],
                'artist': song['artist'],
                'release_month': release_month
            })
        else:
            spotify_release_months.append({
                'title': song['title'],
                'artist': song['artist'],
                'release_month': None
            })
    else:
        spotify_release_months.append({
            'title': song['title'],
            'artist': song['artist'],
            'release_month': None
        })

spotify_release_months

