# Great, we can extract the release month for each song in the missing_release list using this approach.
# Let's loop through all missing songs, search for each, and collect their release months.
# We'll store the results as a dict: {(title, tuple(artists)): release_month}

release_months = {}

for song in missing_release:
    query = f"{song['title']} {song['artists'][0]}"
    results = apis.spotify.search_songs(query=query, page_limit=3)
    # Find the result with exact title and at least one matching artist
    found = None
    for r in results:
        if r["title"].lower() == song["title"].lower():
            result_artists = set(a["name"].lower() for a in r["artists"])
            song_artists = set(a.lower() for a in song["artists"])
            if result_artists & song_artists:
                found = r
                break
    if found:
        release_date = found["release_date"]
        release_month = datetime.fromisoformat(release_date).strftime("%m/%Y")
        release_months[(song["title"], tuple(song["artists"]))] = release_month
    else:
        release_months[(song["title"], tuple(song["artists"]))] = None

print(release_months)

